import subprocess
import os
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp', 'pdf']

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert documents between formats using LibreOffice headless mode."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')

    if output_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Unsupported format: {output_format}'}), 400

    # Save uploaded file to temp directory
    tmp_dir = tempfile.mkdtemp(prefix='convert_')
    input_path = os.path.join(tmp_dir, uploaded.filename)
    uploaded.save(input_path)

    # Additional processing options from user
    extra_args = request.form.get('options', '')

    # Build conversion command
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {tmp_dir} {input_path}'

    # Append user-specified options for advanced conversions
    if extra_args:
        cmd = f'{cmd} {extra_args}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=tmp_dir
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        # Find output file
        output_file = None
        for f in os.listdir(tmp_dir):
            if f.endswith(f'.{output_format}') and f != uploaded.filename:
                output_file = os.path.join(tmp_dir, f)
                break

        if output_file and os.path.exists(output_file):
            from flask import send_file
            return send_file(output_file, as_attachment=True)
        else:
            return jsonify({'error': 'Output file not found'}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/metadata', methods=['GET'])
def get_metadata():
    """Extract metadata from a previously converted document."""
    filepath = request.args.get('path', '')
    if not filepath or '..' in filepath:
        return jsonify({'error': 'Invalid path'}), 400

    cmd = f'exiftool -json {filepath}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=10)
    return jsonify({'metadata': result.stdout.decode('utf-8', errors='replace')})


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
